import type { BinaryStudyScheduleSettings, CardReviewStateSnapshot } from "@/features/study/lib/reviewScheduler";
import { normalizeStudyTimeMs } from "@/features/study/lib/studyTime";
import {
  estimateStudyTimeForCards,
  estimateStudyTimeForCounts,
  type StudyTimeEstimate,
  type StudyTimeEstimatorProfile,
} from "@/features/study/lib/studyTimeEstimator";
import { dedupeDeckIds, normalizeDeckName } from "@/lib/decks";
import type { CardActivity, Deck, StudyReviewLog, StudyTimeTotals } from "@/lib/types";

const collator = new Intl.Collator(undefined, {
  numeric: true,
  sensitivity: "base",
});

export type DeckBrowserRow = {
  id: string;
  title: string;
  fullPath: string;
  depth: number;
  ancestorIds: string[];
  hasChildren: boolean;
  actualDeck: Deck | null;
  descendantDeckIds: string[];
  totalCards: number;
  studyMs?: number;
  cramMs?: number;
  newCount: number;
  learnCount: number;
  dueCount: number;
  studyEstimate?: StudyTimeEstimate;
};

type MutableDeckNode = {
  id: string;
  title: string;
  fullPath: string;
  depth: number;
  children: Map<string, MutableDeckNode>;
  actualDeck: Deck | null;
  descendantDeckIds: Set<string>;
  cardIds: Set<string>;
  studyMs: number;
  cramMs: number;
};

function splitDeckSegments(name: string) {
  return normalizeDeckName(name)
    .split("/")
    .map((segment) => normalizeDeckName(segment))
    .filter(Boolean);
}

function compareNodeNames(left: MutableDeckNode, right: MutableDeckNode) {
  return collator.compare(left.title, right.title);
}

export function buildDeckBrowserRows(
  decks: readonly Deck[],
  totalCardsByNodeId: Readonly<Record<string, number>>,
  reviewCards: readonly CardActivity[],
  reviewStates: Readonly<CardReviewStateSnapshot>,
  deckPathTimes: Readonly<Record<string, StudyTimeTotals>> = {},
  options?: {
    estimateProfile?: StudyTimeEstimatorProfile;
    studyReviewLogs?: readonly StudyReviewLog[];
    schedulerSettings?: BinaryStudyScheduleSettings;
    now?: Date;
  },
) {
  const rootNodes = new Map<string, MutableDeckNode>();
  const nodeAncestorsByDeckId = new Map<string, MutableDeckNode[]>();
  const cardById = new Map(reviewCards.map((card) => [card.id, card]));

  for (const deck of decks) {
    const segments = splitDeckSegments(deck.name);
    if (segments.length === 0) continue;

    let parent: MutableDeckNode | null = null;
    let parentCollection = rootNodes;
    const ancestors: MutableDeckNode[] = [];
    const pathSegments: string[] = [];
    const keySegments: string[] = [];

    for (const segment of segments) {
      pathSegments.push(segment);
      keySegments.push(segment.toLowerCase());

      const nodeId = keySegments.join("/");
      let node = parentCollection.get(nodeId);

      if (!node) {
        node = {
          id: nodeId,
          title: segment,
          fullPath: pathSegments.join("/"),
          depth: ancestors.length,
          children: new Map(),
          actualDeck: null,
          descendantDeckIds: new Set(),
          cardIds: new Set(),
          studyMs: 0,
          cramMs: 0,
        };
        parentCollection.set(nodeId, node);
      }

      ancestors.push(node);
      parent = node;
      parentCollection = node.children;
    }

    if (parent) {
      parent.actualDeck = deck;
    }

    for (const ancestor of ancestors) {
      ancestor.descendantDeckIds.add(deck.id);
    }

    nodeAncestorsByDeckId.set(deck.id, ancestors);
  }

  for (const card of reviewCards) {
    const touchedNodeIds = new Set<string>();
    for (const deckId of dedupeDeckIds(card.tagIds)) {
      const ancestors = nodeAncestorsByDeckId.get(deckId);
      if (!ancestors) continue;
      for (const ancestor of ancestors) {
        if (touchedNodeIds.has(ancestor.id)) continue;
        touchedNodeIds.add(ancestor.id);
        ancestor.cardIds.add(card.id);
      }
    }
  }

  const allNodes: MutableDeckNode[] = [];
  function collectNodes(node: MutableDeckNode) {
    allNodes.push(node);
    for (const child of node.children.values()) collectNodes(child);
  }
  for (const node of rootNodes.values()) collectNodes(node);

  for (const node of allNodes) {
    const time = deckPathTimes[node.id];
    node.studyMs = normalizeStudyTimeMs(time?.studyMs);
    node.cramMs = normalizeStudyTimeMs(time?.cramMs);
  }

  const rows: DeckBrowserRow[] = [];

  function visit(node: MutableDeckNode, ancestorIds: string[]) {
    const descendantDeckIds = Array.from(node.descendantDeckIds);
    let learnCount = 0;
    let dueCount = 0;

    for (const cardId of node.cardIds) {
      const state = reviewStates[cardId];
      if (!state) continue;
      if (state.bucket === "learn") {
        learnCount += 1;
      } else {
        dueCount += 1;
      }
    }

    const totalCards = totalCardsByNodeId[node.id] ?? 0;
    const newCount = Math.max(0, totalCards - learnCount - dueCount);
    const nodeCards = Array.from(node.cardIds)
      .map((cardId) => cardById.get(cardId))
      .filter((card): card is CardActivity => Boolean(card));
    const studyEstimate =
      options?.studyReviewLogs && options.schedulerSettings && nodeCards.length > 0
        ? estimateStudyTimeForCards(
            nodeCards,
            reviewStates,
            options.studyReviewLogs,
            options.schedulerSettings,
            { mode: "study", now: options.now },
          )
        : options?.estimateProfile
          ? estimateStudyTimeForCounts({ newCount, learnCount, dueCount }, options.estimateProfile)
          : undefined;

    rows.push({
      id: node.id,
      title: node.title,
      fullPath: node.fullPath,
      depth: node.depth,
      ancestorIds,
      hasChildren: node.children.size > 0,
      actualDeck: node.actualDeck,
      descendantDeckIds,
      totalCards,
      studyMs: node.studyMs,
      cramMs: node.cramMs,
      newCount,
      learnCount,
      dueCount,
      studyEstimate,
    });

    const sortedChildren = Array.from(node.children.values()).sort(compareNodeNames);
    for (const child of sortedChildren) {
      visit(child, [...ancestorIds, node.id]);
    }
  }

  for (const node of Array.from(rootNodes.values()).sort(compareNodeNames)) {
    visit(node, []);
  }

  return rows;
}

"use client";

import {
  type AdaptiveFsrsCalibrationState,
  applyBinaryReviewResult,
  buildBinaryReviewState,
  removeBinaryReviewStates,
  rescheduleBinaryReviewSnapshot,
  type BinaryStudyResult,
  type BinaryStudyScheduleSettings,
  type CardReviewState,
  type CardReviewStateSnapshot,
} from "@/features/study/lib/reviewScheduler";

type StoreFile = {
  byCardId: CardReviewStateSnapshot;
};

const KEY_PREFIX = "simplecards.reviewStates.";
const LOCAL_KEY = KEY_PREFIX + "local";

function reviewStateKey(userId?: string | null) {
  return KEY_PREFIX + (userId?.trim() || "local");
}

function loadStore(key: string): StoreFile {
  if (typeof window === "undefined") return { byCardId: {} };

  const parseStore = (raw: string | null): StoreFile | null => {
    if (!raw) return null;
    try {
      const parsed = JSON.parse(raw) as unknown;
      if (
        parsed &&
        typeof parsed === "object" &&
        "byCardId" in parsed &&
        (parsed as { byCardId?: unknown }).byCardId &&
        typeof (parsed as { byCardId?: unknown }).byCardId === "object"
      ) {
        return {
          byCardId: {
            ...((parsed as { byCardId: CardReviewStateSnapshot }).byCardId ??
              {}),
          },
        };
      }
      return null;
    } catch {
      return null;
    }
  };

  return parseStore(window.localStorage.getItem(key))
    ?? parseStore(window.localStorage.getItem(LOCAL_KEY))
    ?? { byCardId: {} };
}

function saveStore(key: string, file: StoreFile) {
  if (typeof window === "undefined") return;
  window.localStorage.setItem(key, JSON.stringify(file));
}

export function getStoredReviewStates(userId?: string | null) {
  return loadStore(reviewStateKey(userId)).byCardId;
}

export function saveStoredReviewStates(
  userId: string | null | undefined,
  snapshot: CardReviewStateSnapshot,
) {
  saveStore(reviewStateKey(userId), { byCardId: snapshot });
  return snapshot;
}

export function applyStoredReviewResult(
  userId: string | null | undefined,
  cardId: string,
  result: BinaryStudyResult,
  settings: Partial<BinaryStudyScheduleSettings>,
  reviewedAt = new Date(),
  calibrationState?: AdaptiveFsrsCalibrationState | null,
) {
  const key = reviewStateKey(userId);
  const file = loadStore(key);
  const next = applyBinaryReviewResult(
    file.byCardId,
    cardId,
    result,
    settings,
    reviewedAt,
    calibrationState,
  );
  saveStore(key, { byCardId: next });
  return next;
}

export function recordStoredReviewResult(
  userId: string | null | undefined,
  cardId: string,
  result: BinaryStudyResult,
  settings: Partial<BinaryStudyScheduleSettings>,
  reviewedAt = new Date(),
  calibrationState?: AdaptiveFsrsCalibrationState | null,
): {
  snapshot: CardReviewStateSnapshot;
  previousState: CardReviewState | null;
  nextState: CardReviewState;
} {
  const key = reviewStateKey(userId);
  const file = loadStore(key);
  const previousState = file.byCardId[cardId] ?? null;
  const nextState = buildBinaryReviewState(
    cardId,
    result,
    settings,
    reviewedAt,
    previousState,
    calibrationState,
  );
  const snapshot = {
    ...file.byCardId,
    [cardId]: nextState,
  };
  saveStore(key, { byCardId: snapshot });
  return { snapshot, previousState, nextState };
}

export function rescheduleStoredReviewStates(
  userId: string | null | undefined,
  settings: Partial<BinaryStudyScheduleSettings>,
) {
  const key = reviewStateKey(userId);
  const file = loadStore(key);
  const next = rescheduleBinaryReviewSnapshot(
    file.byCardId,
    settings,
  );
  saveStore(key, { byCardId: next });
  return next;
}

export function removeStoredReviewStates(
  userId: string | null | undefined,
  cardIds: readonly string[],
) {
  const key = reviewStateKey(userId);
  const file = loadStore(key);
  const next = removeBinaryReviewStates(file.byCardId, cardIds);
  saveStore(key, { byCardId: next });
  return next;
}

export function restoreStoredReviewState(
  userId: string | null | undefined,
  cardId: string,
  previousState: CardReviewState | null | undefined,
) {
  const key = reviewStateKey(userId);
  const file = loadStore(key);
  const next = { ...file.byCardId };
  if (previousState) {
    next[cardId] = { ...previousState, cardId };
  } else {
    delete next[cardId];
  }
  saveStore(key, { byCardId: next });
  return next;
}

