function addMinutesIso(baseIso: string, minutes: number) {
  const baseMs = Date.parse(baseIso);
  const normalizedBase = Number.isFinite(baseMs) ? baseMs : Date.now();
  return new Date(normalizedBase + Math.max(0, minutes) * 60_000).toISOString();
}

function formatDelayedRepeatWait(dueAt: string, nowMs: number) {
  const dueAtMs = Date.parse(dueAt);
  if (!Number.isFinite(dueAtMs)) return "soon";
  const remainingMinutes = Math.max(0, Math.ceil((dueAtMs - nowMs) / 60_000));
  return formatStudyInterval(remainingMinutes);
}

function useDeckMobileViewport() {
  const [mobile, setMobile] = React.useState(false);

  React.useEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const media = window.matchMedia("(min-width: 1024px)");
    if (!media) return;
    const sync = () => setMobile(!media.matches);
    sync();
    media.addEventListener?.("change", sync);
    media.addListener?.(sync);
    return () => {
      media.removeEventListener?.("change", sync);
      media.removeListener?.(sync);
    };
  }, []);

  return mobile;
}

