function isHydratedStudyCard(card: Card) {
  return (
    card.question.trim().length > 0 ||
    card.answer.trim().length > 0 ||
    card.tagNames.length > 0 ||
    card.folderPath.trim().length > 0
  );
}

function mergeStudyCards(previous: Card[], resolved: Card[]) {
  if (resolved.length === 0) return previous;
  const resolvedById = new Map(resolved.map((card) => [card.id, card] as const));
  return previous.map((card) => resolvedById.get(card.id) ?? card);
}

function getUpcomingStudyCardIds(
  session: StudySession,
  cards: readonly Card[],
  aheadCount = STUDY_PREFETCH_AHEAD_COUNT,
) {
  const current = getCurrentCard(session);
  const ids: string[] = [];

  if (current) {
    ids.push(current.id);
    ids.push(...collectChainDescendantCardIds(cards, [current.id]));
    ids.push(...session.queue.slice(session.index + 1).map((card) => card.id));
    return Array.from(new Set(ids)).slice(0, aheadCount + 1);
  }

  ids.push(...session.delayedRepeats.map((repeat) => repeat.card.id));
  return Array.from(new Set(ids)).slice(0, aheadCount);
}

function findUnhydratedUpcomingSessionCardIds(
  session: StudySession,
  cards: readonly Card[],
  aheadCount = 0,
) {
  const byId = new Map(cards.map((card) => [card.id, card] as const));
  return getUpcomingStudyCardIds(session, cards, aheadCount).filter((id) => {
    const card = byId.get(id);
    return card ? !isHydratedStudyCard(card) : false;
  });
}

function mergeIncomingStudyCards(previous: Card[], incoming: Card[]) {
  if (incoming.length === 0) return [];

  const previousById = new Map(previous.map((card) => [card.id, card] as const));

  return incoming.map((card) => {
    const existing = previousById.get(card.id);
    if (!existing) return card;
    if (isHydratedStudyCard(card)) return card;
    if (!isHydratedStudyCard(existing)) return card;

    return {
      ...card,
      question: existing.question,
      answer: existing.answer,
      folderPath: existing.folderPath || card.folderPath,
      folderPathNames:
        existing.folderPathNames.length > 0
          ? existing.folderPathNames
          : card.folderPathNames,
      tagNames: existing.tagNames.length > 0 ? existing.tagNames : card.tagNames,
      tagPaths: existing.tagPaths.length > 0 ? existing.tagPaths : card.tagPaths,
    };
  });
}

function buildStudyTimeByCardId(cards: readonly Card[]) {
  const out: Record<string, StudyTimeTotals> = {};
  for (const card of cards) {
    const studyMs = normalizeStudyTimeMs(card.studyMs);
    const cramMs = normalizeStudyTimeMs(card.cramMs);
    if (studyMs <= 0 && cramMs <= 0) continue;
    out[card.id] = { studyMs, cramMs };
  }
  return out;
}

function mergeStudyTimeByCardId(
  previous: Record<string, StudyTimeTotals>,
  incoming: Record<string, StudyTimeTotals>,
) {
  let changed = false;
  const next = { ...previous };
  for (const [cardId, time] of Object.entries(incoming)) {
    const current = next[cardId] ?? { studyMs: 0, cramMs: 0 };
    const studyMs = Math.max(normalizeStudyTimeMs(current.studyMs), normalizeStudyTimeMs(time.studyMs));
    const cramMs = Math.max(normalizeStudyTimeMs(current.cramMs), normalizeStudyTimeMs(time.cramMs));
    if (studyMs === current.studyMs && cramMs === current.cramMs) continue;
    next[cardId] = { studyMs, cramMs };
    changed = true;
  }
  return changed ? next : previous;
}

