function rebuildCardPageData(
  previous: InfiniteData<CardPageResult, number>,
  items: CardPageItem[],
) {
  const hasMore = (previous.pages.at(-1)?.nextOffset ?? null) !== null;
  return buildCardPageData(items, { hasMore });
}

function applyStudyTimeIncrement<T extends { id: string; studyMs?: number; cramMs?: number }>(
  item: T,
  incrementsByCardId: ReadonlyMap<string, StudyTimeTotals>,
): T {
  const increment = incrementsByCardId.get(item.id);
  if (!increment) return item;
  const studyMs = normalizeStudyTimeMs(item.studyMs) + normalizeStudyTimeMs(increment.studyMs);
  const cramMs = normalizeStudyTimeMs(item.cramMs) + normalizeStudyTimeMs(increment.cramMs);
  return {
    ...item,
    ...(studyMs > 0 ? { studyMs } : {}),
    ...(cramMs > 0 ? { cramMs } : {}),
  };
}

function buildStudyTimeIncrementMap(entries: readonly StudyTimeEntry[]) {
  return new Map(
    summarizeStudyTimeEntries(entries).map((entry) => [
      entry.cardId,
      {
        studyMs: normalizeStudyTimeMs(entry.studyMs),
        cramMs: normalizeStudyTimeMs(entry.cramMs),
      },
    ] as const),
  );
}

function sumStudyTime(items: ReadonlyArray<Partial<StudyTimeTotals>>) {
  return items.reduce<StudyTimeTotals>(
    (total, item) => addStudyTimeTotals(total, item),
    { studyMs: 0, cramMs: 0 },
  );
}

function upsertSortedCardPageItem(
  previous: InfiniteData<CardPageResult, number>,
  nextPageItem: CardPageItem,
  sortMode: CardSortMode,
  options?: { isCreate?: boolean; visible?: boolean },
) {
  const visible = options?.visible ?? true;
  const isCreate = options?.isCreate ?? false;
  const loadedItems = previous.pages.flatMap((page) => page.items);
  const hasMore = (previous.pages.at(-1)?.nextOffset ?? null) !== null;
  const alreadyLoaded = loadedItems.some((item) => item.id === nextPageItem.id);
  const loadedAllCards = !hasMore;
  const remainingItems = loadedItems.filter((item) => item.id !== nextPageItem.id);
  const sortedItems = visible
    ? sortCardsByMode([nextPageItem, ...remainingItems], sortMode)
    : remainingItems;

  let targetLoadedCount = loadedItems.length;
  if (isCreate && visible && loadedAllCards) {
    targetLoadedCount += 1;
  } else if (!visible && alreadyLoaded) {
    targetLoadedCount = Math.max(0, targetLoadedCount - 1);
  }

  return buildCardPageData(sortedItems.slice(0, targetLoadedCount), { hasMore });
}

function normalizeDeckPathName(value: string | null | undefined) {
  return normalizeDeckName(value)
    .split("/")
    .map(normalizeDeckName)
    .filter(Boolean)
    .join("/");
}

function addUniqueId(ids: string[], id: string) {
  return ids.includes(id) ? ids : [...ids, id];
}

function removeId(ids: string[], id: string) {
  return ids.filter((candidate) => candidate !== id);
}

function upsertDeckList(decks: Deck[], deck: Deck) {
  const deckNameKey = normalizeDeckNameKey(deck.name);
  const withoutDeck = decks.filter(
    (candidate) =>
      candidate.id !== deck.id &&
      normalizeDeckNameKey(candidate.name) !== deckNameKey,
  );
  return [...withoutDeck, deck];
}

function replaceDeckInList(decks: Deck[], previousDeckId: string, deck: Deck) {
  const deckNameKey = normalizeDeckNameKey(deck.name);
  const withoutDeck = decks.filter(
    (candidate) =>
      candidate.id !== previousDeckId &&
      candidate.id !== deck.id &&
      normalizeDeckNameKey(candidate.name) !== deckNameKey,
  );
  return [...withoutDeck, deck];
}

