const recordStudyAnswer = React.useCallback(
  (
    cardId: string,
    result: BinaryStudyResult,
    meta: { mode: "study" | "cram"; durationMs: number; reviewedAt: string; sessionId: string },
  ) => {
    const recorded = meta.mode === "study"
      ? recordStoredReviewResult(
          userId,
          cardId,
          result,
          schedulerSettings,
          new Date(meta.reviewedAt),
          adaptiveFsrsCalibrationState,
        )
      : null;
    if (recorded) {
      reviewStatesRef.current = recorded.snapshot;
      setReviewStates(recorded.snapshot);
    }

    const answerMeta: StudyAnswerUndoMeta = {
      cardId,
      result,
      mode: meta.mode,
      durationMs: meta.durationMs,
      reviewedAt: meta.reviewedAt,
      sessionId: meta.sessionId,
    };
    const undoKey = studyAnswerUndoKey(answerMeta);
    if (meta.mode === "study") {
      studyAnswerUndoStateRef.current.set(undoKey, {
        previousState: recorded?.previousState ?? null,
      });
      while (studyAnswerUndoStateRef.current.size > 200) {
        const oldest = studyAnswerUndoStateRef.current.keys().next().value;
        if (!oldest) break;
        studyAnswerUndoStateRef.current.delete(oldest);
      }
    }

    const entry = {
      cardId,
      mode: meta.mode,
      result,
      durationMs: meta.durationMs,
      reviewedAt: meta.reviewedAt,
      sessionId: meta.sessionId,
      previousState: recorded?.previousState ?? null,
      nextState: recorded?.nextState ?? null,
    };
    const optimisticId = `pending-${meta.sessionId}-${cardId}-${meta.reviewedAt}`;
    const optimisticLog: StudyReviewLog = {
      id: optimisticId,
      cardId,
      mode: meta.mode,
      result,
      durationMs: meta.durationMs,
      reviewedAt: meta.reviewedAt,
      sessionId: meta.sessionId,
      previousState: recorded?.previousState ?? null,
      nextState: recorded?.nextState ?? null,
      createdAt: meta.reviewedAt,
    };
    queryClient.setQueryData<StudyReviewLog[]>(studyReviewLogsKey, (previous) =>
      sortReviewLogsAscending([...(previous ?? []), optimisticLog]).slice(-STUDY_REVIEW_LOG_HISTORY_LIMIT),
    );

    void api.recordStudyReviewLogs([entry])
      .then((savedLogs) => {
        if (cancelledStudyAnswerSaveKeysRef.current.has(undoKey)) {
          cancelledStudyAnswerSaveKeysRef.current.delete(undoKey);
          queryClient.setQueryData<StudyReviewLog[]>(studyReviewLogsKey, (previous) =>
            sortReviewLogsAscending(
              (previous ?? []).filter(
                (log) =>
                  log.id !== optimisticId &&
                  !savedLogs.some((saved) => saved.id === log.id) &&
                  !matchesStudyAnswerUndo(log, answerMeta),
              ),
            ).slice(-STUDY_REVIEW_LOG_HISTORY_LIMIT),
          );
          void api.deleteStudyReviewLogs({
            cardId,
            mode: meta.mode,
            result,
            reviewedAt: meta.reviewedAt,
            sessionId: meta.sessionId,
          }).catch((error) => {
            console.warn("Failed to delete undone study review log", error);
          });
          return;
        }

        queryClient.setQueryData<StudyReviewLog[]>(studyReviewLogsKey, (previous) =>
          sortReviewLogsAscending([
            ...(previous ?? []).filter((log) => log.id !== optimisticId),
            ...savedLogs,
          ]).slice(-STUDY_REVIEW_LOG_HISTORY_LIMIT),
        );
      })
      .catch((error) => {
        cancelledStudyAnswerSaveKeysRef.current.delete(undoKey);
        console.warn("Failed to save study review log", error);
      });
  },
  [
    adaptiveFsrsCalibrationState,
    queryClient,
    schedulerSettings,
    studyReviewLogsKey,
    userId,
  ],
);

const undoStudyAnswer = React.useCallback(
  (meta: StudyAnswerUndoMeta) => {
        cancelledStudyAnswerSaveKeysRef.current.delete(undoKey);
      }, 60_000);
    }

    const savedUndo = studyAnswerUndoStateRef.current.get(undoKey);
    studyAnswerUndoStateRef.current.delete(undoKey);
    let previousState =
      savedUndo && meta.mode === "study"
        ? savedUndo.previousState
        : undefined;

    queryClient.setQueryData<StudyReviewLog[]>(studyReviewLogsKey, (previous) => {
      if (!previous) return previous;
      const remaining: StudyReviewLog[] = [];
      for (const log of previous) {
        if (!matchesStudyAnswerUndo(log, meta)) {
          remaining.push(log);
          continue;
        }
        if (previousState === undefined && isCardReviewState(log.previousState)) {
          previousState = log.previousState;
        } else if (previousState === undefined) {
          previousState = null;
        }
      }
      return sortReviewLogsAscending(remaining).slice(-STUDY_REVIEW_LOG_HISTORY_LIMIT);
    });

    if (meta.mode === "study" && previousState !== undefined) {
      const nextReviewStates = restoreStoredReviewState(userId, meta.cardId, previousState);
      reviewStatesRef.current = nextReviewStates;
      setReviewStates(nextReviewStates);
    }

    void api.deleteStudyReviewLogs({
      cardId: meta.cardId,
      mode: meta.mode,
      result: meta.result,
      reviewedAt: meta.reviewedAt,
      sessionId: meta.sessionId,
    }).catch((error) => {
      console.warn("Failed to delete undone study review log", error);
    });
  },
  [queryClient, studyReviewLogsKey, userId],
);

