export function estimateRetentionIntervalMultiplier(
  targetRetentionPercent: number,
  baselineRetentionPercent = DEFAULT_TARGET_RETENTION_PERCENT,
) {
  const target = normalizeTargetRetentionPercent(targetRetentionPercent) / 100;
  const baseline = normalizeTargetRetentionPercent(baselineRetentionPercent) / 100;
  const raw = Math.log(target) / Math.log(baseline);
  if (!Number.isFinite(raw) || raw <= 0) return 1;
  return raw;
}

