  full: (scope: string, cardId: string) =>
    ['cards', scope, 'full', cardId] as const,
}

type SnapshotKind = 'decks' | 'library' | 'cards-page'

type PersistedQuerySnapshot<T> = {
  updatedAt: number
  value: T
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value)
}

function isDeck(value: unknown): value is Deck {
  return (
    isRecord(value) &&
    typeof value.id === 'string' &&
    typeof value.name === 'string' &&
    (value.parentId === null || typeof value.parentId === 'string') &&
    typeof value.createdAt === 'string' &&
    typeof value.updatedAt === 'string'
  )
}

function isDeckArray(value: unknown): value is Deck[] {
  return Array.isArray(value) && value.every(isDeck)
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === 'string')
}

function isNumberRecord(value: unknown): value is Record<string, number> {
  return isRecord(value) && Object.values(value).every((item) => typeof item === 'number')
}

function isDeckActivityRollupRecord(value: unknown): value is LibraryBootstrap['deckRollups'] {
  return (
    isRecord(value) &&
    Object.values(value).every((item) => (
      isRecord(item) &&
      typeof item.totalCards === 'number' &&
      (item.latestCardCreatedAt === null || typeof item.latestCardCreatedAt === 'string') &&
      (item.studyMs === undefined || typeof item.studyMs === 'number') &&
      (item.cramMs === undefined || typeof item.cramMs === 'number')
    ))
  )
}

function isStudyTimeTotalsRecord(value: unknown): value is NonNullable<LibraryBootstrap['deckPathTimes']> {
  return (
    isRecord(value) &&
    Object.values(value).every((item) => (
      isRecord(item) &&
      typeof item.studyMs === 'number' &&
      typeof item.cramMs === 'number'
    ))
  )
}

function isLibraryBootstrap(value: unknown): value is LibraryBootstrap {
  return (
    isRecord(value) &&
    isDeckArray(value.decks) &&
    isStringArray(value.hiddenCardIds) &&
    isDeckActivityRollupRecord(value.deckRollups) &&
    isNumberRecord(value.deckPathCounts) &&
    (value.deckPathTimes === undefined || isStudyTimeTotalsRecord(value.deckPathTimes))
  )
}

function isCardPreview(value: unknown) {
  return (
    isRecord(value) &&
    typeof value.text === 'string' &&
    (value.imageSrc === null || typeof value.imageSrc === 'string') &&
    typeof value.imageCount === 'number' &&
    (value.imageRef === undefined || value.imageRef === null || typeof value.imageRef === 'string') &&
    (
      value.imageVariant === undefined ||
      value.imageVariant === null ||
      value.imageVariant === 'deck_thumb' ||
      value.imageVariant === 'deck_thumb_v2' ||
      value.imageVariant === 'original'
    )
  )
}

function isCardPageItem(value: unknown) {
  return (
    isRecord(value) &&
    typeof value.id === 'string' &&
    (value.parentCardId === null || typeof value.parentCardId === 'string') &&
    isStringArray(value.tagIds) &&
    isStringArray(value.tagNames) &&
    isCardPreview(value.questionPreview) &&
    isCardPreview(value.answerPreview) &&
    (value.studyMs === undefined || typeof value.studyMs === 'number') &&
    (value.cramMs === undefined || typeof value.cramMs === 'number') &&
    typeof value.createdAt === 'string' &&
    typeof value.updatedAt === 'string'
  )
}

function isCardPageResult(value: unknown): value is CardPageResult {
  return (
    isRecord(value) &&
    Array.isArray(value.items) &&
    value.items.every(isCardPageItem) &&
    (value.nextOffset === null || typeof value.nextOffset === 'number')
  )
}

export function persistedCardQuerySnapshotKey(kind: SnapshotKind, scope: string) {
  return `${PERSISTED_QUERY_SNAPSHOT_PREFIX}:${kind}:${scope}`
}

export function persistedCardPageSnapshotKey(
  scope: string,
  selectedDeckKey: string,
  sortMode: CardSortMode,
) {
  return persistedCardQuerySnapshotKey('cards-page', `${scope}:${selectedDeckKey}:${sortMode}`)
}

function persistedCardPageLastSnapshotKey(selectedDeckKey: string, sortMode: CardSortMode) {
  return `${PERSISTED_CARD_PAGE_LAST_PREFIX}:${selectedDeckKey}:${sortMode}`
}

function isCardPageSnapshotForSelection(
  key: string | null,
  selectedDeckKey: string,
  sortMode: CardSortMode,
) {
  return Boolean(
    key &&
    key.startsWith(`${PERSISTED_QUERY_SNAPSHOT_PREFIX}:cards-page:`) &&
    key.endsWith(`:${selectedDeckKey}:${sortMode}`),
  )
}

function readPersistedQuerySnapshotRecordFromKey<T>(
  key: string,
  isValue: (value: unknown) => value is T,
) {
  if (typeof window === 'undefined') return undefined

  try {
    const raw = window.localStorage.getItem(key)
    if (!raw) return undefined

    const parsed = JSON.parse(raw) as unknown
    if (
      !isRecord(parsed) ||
      typeof parsed.updatedAt !== 'number' ||
      !isValue(parsed.value)
    ) {
      return undefined
    }

    return parsed as PersistedQuerySnapshot<T>
  } catch {
    return undefined
  }
}

