async getCardActivity(selectedDeckIds?: string[] | string | null): Promise<CardActivity[]> {
  const normalizedDeckIds = normalizeIncomingTagIds(selectedDeckIds)
  const selectedDeckIdSet =
    normalizedDeckIds.length > 0 ? new Set(normalizedDeckIds) : null
  const timeByCardId = getLocalStudyTimeByCardId(null)

  return load().cards
    .filter((card) =>
      !selectedDeckIdSet || card.tagIds.some((tagId) => selectedDeckIdSet.has(tagId)),
    )
    .map((card) => ({
      id: card.id,
      parentCardId: card.parentCardId,
      tagIds: card.tagIds,
      createdAt: card.createdAt,
    }))
    .map((card) => applyStudyTime(card, timeByCardId))
},

async getCardActivityByIds(cardIds: string[]): Promise<CardActivity[]> {
  const requestedIds = new Set(cardIds.map((cardId) => String(cardId ?? '').trim()).filter(Boolean))
  if (requestedIds.size === 0) return []
  const timeByCardId = getLocalStudyTimeByCardId(null)

  return load().cards
    .filter((card) => requestedIds.has(card.id))
    .map((card) => ({
      id: card.id,
      parentCardId: card.parentCardId,
      tagIds: card.tagIds,
      createdAt: card.createdAt,
    }))
    .map((card) => applyStudyTime(card, timeByCardId))
},
