export async function getCardActivity(
  client: SupabaseClient,
  userId: string,
  selectedDeckIds?: string[] | string | null,
) {
  const normalizedDeckIds = Array.isArray(selectedDeckIds)
    ? dedupeDeckIds(selectedDeckIds)
    : typeof selectedDeckIds === 'string' && selectedDeckIds.trim()
      ? [selectedDeckIds.trim()]
      : []
  const activities = (await listCardActivityRows(client, userId, normalizedDeckIds)).map((row) => toCardActivity(row))
  const timeByCardId = await buildStudyTimeByCardId(client, userId, activities.map((card) => card.id), { optional: true })
  return activities.map((card) => applyStudyTime(card, timeByCardId))
}

export async function getCardActivityByIds(
  client: SupabaseClient,
  userId: string,
  cardIds: readonly string[],
) {
  const activities = (await listCardActivityRowsByIds(client, userId, cardIds)).map((row) => toCardActivity(row))
  const timeByCardId = await buildStudyTimeByCardId(client, userId, activities.map((card) => card.id), { optional: true })
  return activities.map((card) => applyStudyTime(card, timeByCardId))
}

