function parseDeckQueryParam(param?: string | null) {
  return typeof param === 'string' && param.trim()
    ? param
        .split(',')
        .map((value) => value.trim())
        .filter(Boolean)
    : []
}

export function parseSelectedDeckIds(routeDeckId: string | null, decksParam?: string | null, legacyTagsParam?: string | null) {
  const fromQuery = parseDeckQueryParam(decksParam)
  const fromLegacyQuery = parseDeckQueryParam(legacyTagsParam)
  if (fromQuery.length > 0) return dedupeDeckIds(fromQuery)
  if (fromLegacyQuery.length > 0) return dedupeDeckIds(fromLegacyQuery)
  return routeDeckId ? [routeDeckId] : []
}

export const parseSelectedTagIds = parseSelectedDeckIds

export function parseStudyMode(studyParam?: string | null): StudyMode | null {
  if (studyParam === '1' || studyParam === 'review') return 'review'
  if (studyParam === 'cram') return 'cram'
  return null
}

export function parseSelectCardsMode(selectParam?: string | null) {
  return selectParam === '1' || selectParam === 'cards'
}

