  if (normalizedDeckIds.length > 0) params.set('decks', normalizedDeckIds.join(','))
  const studyMode = options?.studyMode ?? (options?.study ? 'review' : null)
  if (studyMode === 'review') params.set('study', '1')
  if (studyMode === 'cram') params.set('study', 'cram')
  if (options?.selectCards) params.set('select', 'cards')

  const query = params.toString()
  return query ? `/cards?${query}` : '/'
}

export function canonicalizeCardsUrl(
  pathname: string,
  studyParam: string | null,
  decksParam?: string | null,
  legacyTagsParam?: string | null,
  selectParam?: string | null,
) {
  const routePrefix = pathname.startsWith('/decks/')
    ? '/decks/'
    : pathname.startsWith('/cards/')
      ? '/cards/'
      : null
  const routeDeckId = routePrefix ? decodeURIComponent(pathname.slice(routePrefix.length)) : null
  return buildCardsUrl(parseSelectedDeckIds(routeDeckId, decksParam, legacyTagsParam), {
    studyMode: parseStudyMode(studyParam),
    selectCards: parseSelectCardsMode(selectParam),
  })
}
  return error instanceof Error ? error.message : String(error);
}

function hasDraggedImageFile(dataTransfer: DataTransfer | null | undefined) {
  if (!dataTransfer) return false;
  return Array.from(dataTransfer.items ?? []).some(
    (item) => item.kind === "file" && item.type.startsWith("image/"),
  );
}

function buildSessionKey(selectedDeckIds: string[], studyMode: StudyMode = "review") {
  const normalized = dedupeDeckIds(selectedDeckIds).sort();
  const base = normalized.length > 0 ? normalized.join("|") : "all";
  return studyMode === "cram" ? `cram:${base}` : base;
}

