function renderRoute({
  pathname = '/',
  searchParams = new URLSearchParams(),
  routeMode = pathname.startsWith('/cards') ? 'cards' : 'decks',
  routeDeckId = null,
}: {
  pathname?: string
  searchParams?: URLSearchParams
  routeMode?: 'decks' | 'cards'
  routeDeckId?: string | null
} = {}) {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: {
        retry: false,
        refetchOnWindowFocus: false,
      },
    },
  })

  return render(
    <QueryClientProvider client={queryClient}>
      <AppRoutingProvider
        router={{ replace: replaceMock }}
        pathname={pathname}
        searchParams={searchParams}
        params={{}}
      >
        <MainAppRoute
          routeMode={routeMode}
          routeDeckId={routeDeckId}
          imageOcclusionEnabled={false}
        />
      </AppRoutingProvider>
    </QueryClientProvider>,
  )
}

function renderDecksRoute() {
  return renderRoute({
    pathname: '/',
    routeMode: 'decks',
  })
}

function renderCardsRoute(selectedDeckIds: string[] = ['tag-bio']) {
  const searchParams = new URLSearchParams()
  if (selectedDeckIds.length > 0) {
    searchParams.set('decks', selectedDeckIds.join(','))
  }
  return renderRoute({
    pathname: '/cards',
    searchParams,
    routeMode: 'cards',
  })
}

function createDeferred<T>() {
  let resolve!: (value: T) => void
  let reject!: (reason?: unknown) => void
  const promise = new Promise<T>((res, rej) => {
    resolve = res
    reject = rej
  })
  return { promise, resolve, reject }
}

async function selectDeck(name: string, deckId: string) {
  fireEvent.click(await screen.findByRole('button', { name }))
  await waitFor(() => expect(replaceMock).toHaveBeenLastCalledWith(`/cards?decks=${deckId}`))
}

async function waitForPreviewCards(count?: number) {
  await waitFor(() => {
    const previewButtons = screen.queryAllByRole('button', { name: 'Preview card' })
    if (typeof count === 'number') {
      expect(previewButtons).toHaveLength(count)
      return
    }
    expect(previewButtons.length).toBeGreaterThan(0)
  })
}

async function returnToDeckHome() {
  fireEvent.click(getPrimaryDecksButton())
  await waitFor(() => expect(replaceMock).toHaveBeenLastCalledWith('/'))
}

function getPrimaryDecksButton() {
  return screen.getAllByRole('button', { name: 'Decks' }).at(0)!
}

function expectVisibleCountLabel(label: string) {
  expect(screen.getAllByText((_content, node) => node?.textContent === label).length).toBeGreaterThan(0)
}

function expectNoVisibleCountLabel(label: string) {
